import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from "../Https/Axios";
import { LoginParent } from "../Https/AdminSideAxiosUrls";

const LoginForm = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  useEffect(() => {
    if (localStorage.getItem('auth')) {
      navigate('/dashboard/home');
    }
  }, [navigate]);

  const handleLogin = (e) => {
    e.preventDefault();
    if (email === 'admin@gmail.com' && password === 'admin123') {
      localStorage.setItem('auth', 'true');
      navigate('/dashboard/home');
    } else {
      alert('Invalid credentials');
    }
  };

  return (
    <div className="login-container  ">
 
 
      <div className="login-box">
        <h2 className='ms-5'>Login in to Admin Dashboard</h2>
        <form onSubmit={handleLogin}>
          <div className="input-container w-100  ">
            <input
            className='rounded-5 bg-light'
              type="email"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div className="input-container w-100 " >
            <input
             className='rounded-5 bg-light'
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>
          <button
            type="submit"
            className="login-button w-100  mt-5"
       
          >
            Login
          </button>
       
        </form>
      </div>
      <div>

    <div className="image-container d-none d-lg-block">
      <img
        src="https://i.postimg.cc/j5SmqQCy/Whats-App-Image-2025-05-08-at-09-30-30-e8015bab.jpg"
        alt="login illustration"
      />
    </div>

      </div>
    </div>
  );
};

export default LoginForm;
