import React, { useEffect, useState } from 'react';
import axios from "../Https/Axios";
import { AdminVideo, UploadVideos } from "../Https/AdminSideAxiosUrls";
import { FaTrash } from 'react-icons/fa';
import { ToastContainer, toast } from "react-toastify";
import Swal from "sweetalert2";
import "react-toastify/dist/ReactToastify.css";
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap/dist/js/bootstrap.bundle.min.js';

const AdminVideoList = () => {
  const [videos, setVideos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [playingVideoId, setPlayingVideoId] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [formData, setFormData] = useState({
    title: '',
    videoUrl: '',
    source: '',
    category: '',
    tags: '',
    comments: ''
  });

  useEffect(() => {
    fetchVideos();
  }, []);

  const handleSearch = (e) => setSearchTerm(e.target.value);

  const fetchVideos = async () => {
    setLoading(true);
    try {
      const res = await axios.get(AdminVideo);
      setTimeout(() => {
        setVideos(res.data);
        setLoading(false);
      }, 2000);
    } catch (error) {
      console.error('Error fetching videos:', error);
      setLoading(false);
      toast.error("Failed to fetch videos.");
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this video?')) return;
    try {
      await axios.delete(`${AdminVideo}/${id}`);
      setVideos(videos.filter((video) => video._id !== id));
      toast.success("Video deleted successfully.");
    } catch (error) {
      console.error('Error deleting video:', error);
      toast.error("Failed to delete video.");
    }
  };

  const getVideoId = (url) => {
    const regExp = /^.*(?:youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
    const match = url.match(regExp);
    return match && match[1].length === 11 ? match[1] : null;
  };

  const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    const payload = {
      title: formData.title,
      url: formData.videoUrl,
      source: formData.source,
      category: formData.category,
      tags: formData.tags.split(',').map(tag => tag.trim()),
      comments: formData.comments ? [formData.comments] : [],
    };

    try {
      await axios.post(UploadVideos, payload);
      Swal.fire({
        icon: 'success',
        title: 'Success!',
        text: 'Video added successfully.',
        confirmButtonColor: '#077A7D',
      });

      setFormData({
        title: '',
        videoUrl: '',
        source: '',
        category: '',
        tags: '',
        comments: ''
      });

      fetchVideos();
    } catch (error) {
      console.error('Error adding video:', error);
      Swal.fire({
        icon: 'error',
        title: 'Error!',
        text: 'Failed to add video.',
        confirmButtonColor: '#d33',
      });
    }
  };

  return (
    <div className="container" style={{ overflowX: 'hidden' }}>
      <ToastContainer />

      {/* Search + Add Video */}
      <div className='d-flex  gap-3  align-items-center mb-3'>
        <div className="col-md-6 col-sm-12 mb-2  w-75">
          <input
            type="text"
            className="form-control rounded-5 w-100 ms-2 bg-light"
            placeholder="Search..."
            value={searchTerm}
            onChange={handleSearch}
          />
        </div>
        <div className="col-md-4 col-sm-12">
          <button
            className="btn bg-warning w-50 rounded-5 mb-2 fw-bold text-white"
            data-bs-toggle="modal"
            data-bs-target="#addVideoModal"
          >
            Add Video
          </button>
        </div>
      </div>

      {/* Loader */}
      {loading && (
        <div className="loader-container">
          <div className="spinner-square">
            <div className="square-1 square"></div>
            <div className="square-2 square"></div>
            <div className="square-3 square"></div>
          </div>
        </div>
      )}

      {/* Video Cards */}
      <div className="row">
        {videos
          .filter((video) => video.title.toLowerCase().includes(searchTerm.toLowerCase()))
          .map((video) => {
            const videoId = getVideoId(video.url);
            const isPlaying = playingVideoId === video._id;

            return (
              <div className="col-sm-12 col-md-10 col-lg-4 mb-4" key={video._id}>
                <div className="card h-100 shadow">
                  <div
                    className="thumbnail"
                    style={{ cursor: 'pointer' }}
                    onClick={() => setPlayingVideoId(isPlaying ? null : video._id)}
                  >
                    {isPlaying ? (
                      <iframe
                        src={`https://www.youtube.com/embed/${videoId}?autoplay=1`}
                        title={video.title}
                        allow="autoplay; encrypted-media"
                        allowFullScreen
                        className="w-100"
                        style={{ height: '200px' }}
                      />
                    ) : (
                      <img
                        src={`https://img.youtube.com/vi/${videoId}/0.jpg`}
                        alt={video.title}
                        className="w-100"
                        style={{ height: '200px', objectFit: 'cover' }}
                      />
                    )}
                  </div>
                  <div className="card-body">
                    <h5 className="card-title">{video.title}</h5>
                    <p className="card-text text-start"><strong>Category:</strong> {video.category || 'N/A'}</p>
                    <p className="card-text text-start"><strong>Tags:</strong> {video.tags?.join(', ') || 'N/A'}</p>
                    <p className="card-text text-start"><strong>Comments:</strong> {video.comments?.join(', ') || 'N/A'}</p>
                  </div>
                  <div className="card-footer bg-white text-end">
                    <button onClick={() => handleDelete(video._id)} className="btn bg-warning btn-sm">
                      <FaTrash /> Delete
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
      </div>

      {/* Add Video Modal */}
      <div className="modal fade" id="addVideoModal" tabIndex="-1" aria-labelledby="addVideoModalLabel" aria-hidden="true">
        <div className="modal-dialog">
          <form onSubmit={handleSubmit}>
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title text-warning">Add Video</h5>
                <button type="button" className="btn-close" data-bs-dismiss="modal" />
              </div>
              <div className="modal-body">
                {/* Form Fields */}
                {['title', 'videoUrl', 'tags', 'comments'].map((field, i) => (
                  <div className="mb-3 text-warning fw-bold" key={i}>
                    <label className="form-label text-capitalize">{field}</label>
                    <input
                      type="text"
                      className="form-control"
                      name={field}
                      value={formData[field]}
                      onChange={handleChange}
                      required={field !== 'comments' && field !== 'tags'}
                    />
                  </div>
                ))}

                {/* Dropdowns */}
                {['source', 'category'].map((field, i) => (
                  <div className="mb-3 text-warning fw-bold" key={i}>
                    <label className="form-label text-capitalize">{field}</label>
                    <select
                      className="form-select"
                      name={field}
                      value={formData[field]}
                      onChange={handleChange}
                      required
                    >
                      <option value="">Select {field}</option>
                      {field === 'source'
                        ? ['YouTube', 'TikTok'].map((v) => <option key={v} value={v}>{v}</option>)
                        : ['Long', 'Short'].map((v) => <option key={v} value={v}>{v}</option>)}
                    </select>
                  </div>
                ))}
              </div>
              <div className="modal-footer">
                <button type="submit" className="btn bg-warning text-white">Upload</button>
                <button type="button" className="btn bg-warning text-white" data-bs-dismiss="modal">Close</button>
              </div>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default AdminVideoList;
