import React, { useState, useEffect } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import {
  FaHome,
  FaUserGraduate,
  FaPlusCircle,
  FaSignOutAlt,
  FaUpload,
  FaVideo,
  FaHistory,
  FaBars,
} from 'react-icons/fa';

const Sidebar = () => {
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isSmallScreen, setIsSmallScreen] = useState(false);

  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 876) {
        setIsSmallScreen(true);
        setIsSidebarOpen(false); // choti screen par default closed
      } else {
        setIsSmallScreen(false);
        setIsSidebarOpen(true); // badi screen par hamesha open
      }
    };

    handleResize(); // initial check
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleToggle = () => {
    if (isSmallScreen) {
      setIsSidebarOpen((prev) => !prev); // toggle kare
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('auth');
    navigate('/');
  };

  return (
    <>
      {/* Toggle Button for Small Screens */}
      {isSmallScreen && (
        <button
          onClick={handleToggle}
          style={{
            position: 'fixed',
            top: 10,
            left: 10,
            zIndex: 1001,
            background: '#b554e2',
            color: '#fff',
            border: 'none',
            padding: '10px',
            borderRadius: '5px',
          }}
        >
          <FaBars />
        </button>
      )}

      <div
        className="sidebar-container"
        style={{
          width: isSidebarOpen ? '280px' : '0',
          overflow: 'hidden',
          transition: 'width 0.3s ease',
          backgroundColor: '#077A7D',
          height: '100vh',
          position: 'fixed',
          top: 0,
          left: 0,
          color: '#fff',
          padding: isSidebarOpen ? '20px' : '0',
          zIndex: 1000,
        }}
      >
        <div className="sidebar-header">
          <span className="header-text">Admin Dashboard</span>
        </div>

        <nav className="sidebar-menu">
          <Link
            to="/dashboard/home"
            className={`sidebar-link ${location.pathname === '/dashboard/home' ? 'active' : ''}`}
          >
            <FaHome className="icon" />
            <span className="label">Home</span>
          </Link>
          <Link
            to="/dashboard/ParentList"
            className={`sidebar-link ${location.pathname === '/dashboard/ParentList' ? 'active' : ''}`}
          >
            <FaUserGraduate className="icon" />
            <span className="label">Parent List</span>
          </Link>
          {/* <Link
            to="/dashboard/AddParent"
            className={`sidebar-link ${location.pathname === '/dashboard/AddParent' ? 'active' : ''}`}
          >
            <FaPlusCircle className="icon" />
            <span className="label">Add Parent</span>
          </Link> */}
          <Link
            to="/dashboard/AllVideoList"
            className={`sidebar-link ${location.pathname === '/dashboard/AllVideoList' ? 'active' : ''}`}
          >
            <FaHistory className="icon" />
            <span className="label">All Video List</span>
          </Link>
          <Link
            to="/dashboard/AdminVideoList"
            className={`sidebar-link ${location.pathname === '/dashboard/AdminVideoList' ? 'active' : ''}`}
          >
            <FaUpload className="icon" />
            <span className="label">Admin Video List</span>
          </Link>
          {/* <Link
            to="/dashboard/AddVideo"
            className={`sidebar-link ${location.pathname === '/dashboard/AddVideo' ? 'active' : ''}`}
          >
            <FaVideo className="icon" />
            <span className="label">Add Video</span>
          </Link> */}
        </nav>

        <button className="sidebar-link logout-button" onClick={handleLogout}>
          <FaSignOutAlt className="icon" />
          <span className="label">Logout</span>
        </button>
      </div>
    </>
  );
};

export default Sidebar;
