import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { FaUsers, FaDollarSign, FaTasks, FaUserPlus, FaVideo } from 'react-icons/fa';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { VideoList } from '../Https/AdminSideAxiosUrls';

export const AdminVideo = 'https://kidsprotect.speckpro.com/api/admin_videos';

const Home = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [usersCount, setUsersCount] = useState(0);
  const [videoCount, setVideoCount] = useState(0);
  const [adminVideoCount, setAdminVideoCount] = useState(0);

  const handleSearch = (e) => {
    setSearchTerm(e.target.value);
  };

  const term = searchTerm.toLowerCase();

  // Fetch total users
  useEffect(() => {
    axios.get('https://kidsprotect.speckpro.com/api/parent')
      .then(res => {
        setUsersCount(res.data.length);
      })
      .catch(err => {
        console.error("Error fetching parents:", err);
      });
  }, []);

  // Fetch total videos
  useEffect(() => {
    axios.get('https://kidsprotect.speckpro.com/api/videos')
      .then(res => {
        setVideoCount(res.data.length);
      })
      .catch(err => {
        console.error("Error fetching videos:", err);
      });
  }, []);

  // Fetch admin videos count
  useEffect(() => {
    axios.get(AdminVideo)
      .then(res => {
        console.log('Admin videos response:', res.data);
        setAdminVideoCount(Array.isArray(res.data) ? res.data.length : 0);
      })
      .catch(err => {
        console.error("Error fetching admin videos:", err);
      });
  }, []);

  // Chart data with first three cards only
  const data = [
    { name: 'Users', value: usersCount },
    { name: 'Videos', value: videoCount },
    { name: 'Admin Videos', value: adminVideoCount },
  ];

  return (
    <div className="container py-4">
      {/* Search Bar */}
      <div className="row mb-4  ">
        <div className="col-md-6 col-sm-12 w-75">
          <input
            type="text"
            className="form-control ms-2 rounded-5 p-2 w-100 bg-light"
            placeholder="Search..."
            value={searchTerm}
            onChange={handleSearch}
          />
        </div>
        <div className="col-lg-3 col-md-6  col-sm-12">
          <button className="btn bg-warning w-50 rounded-5 p-2 fw-bold text-white">Search</button>
        </div>
      </div>

      {/* Cards */}
      <div className="row g-4">
        {(term === '' || 'total users'.includes(term)) && (
          <div className="col-md-8 col-lg-4 col-sm-12 ms-2">
            <div className="card-one text-dark p-4 rounded-4 shadow text-center">
              <div className='w-25 rounded-2 bg-warning mt-4 ms-4' style={{ height: '50px' }}>
                <FaUsers className="icon-style fs-1 text-white mt-1" />
              </div>
              <h5 style={{ marginTop: '-50px' }} className='ms-5'>Total Users</h5>
              <p className="fs-4 ms-5 fw-bold">{usersCount}</p>
            </div>
          </div>
        )}
        {(term === '' || 'revenue'.includes(term) || 'videos'.includes(term)) && (
          <div className="col-md-8 col-lg-4 col-sm-12">
            <div className="card-two text-dark p-4 rounded-4 shadow text-center">
              <div className='w-25 rounded-2 bg-warning mt-4 ms-4' style={{ height: '50px' }}>
                <FaVideo className="icon-style  fs-2 text-white mt-2" />
              </div>
              <h5 style={{ marginTop: '-50px' }} className='ms-5'>Total Videos</h5>
              <p className="fs-4 ms-5 fw-bold">{videoCount}</p>
            </div>
          </div>
        )}
        {(term === '' || 'tasks pending'.includes(term) || 'admin videos'.includes(term)) && (
          <div className="col-md-8 col-lg-4 col-sm-12">
            <div className="card-three text-dark p-4 rounded-4 shadow text-center">
              <div className='w-25 rounded-2 bg-warning mt-4 ms-4' style={{ height: '50px' }}>
                <FaVideo className="icon-style fs-2 text-white mt-2" />
              </div>
              <h5 style={{ marginTop: '-50px' }} className='ms-5'>Admin Videos</h5>
              <p className="fs-4 ms-5 fw-bold">{adminVideoCount}</p>
            </div>
          </div>
        )}
        {(term === '' || 'new sign-ups'.includes(term) || 'signups'.includes(term)) && (
          <div className="col-md-8 col-lg-4 col-sm-12 ms-2">
            <div className="card-four text-dark p-4 rounded-4 shadow text-center">
              <div className='w-25 rounded-2 bg-warning mt-4 ms-4' style={{ height: '50px' }}>
                <FaUserPlus className="icon-style fs-2 text-white mt-2" />
              </div>
              <h5 style={{ marginTop: '-50px' }} className='ms-5'>New Sign-ups</h5>
              <p className="fs-4 ms-5 fw-bold">120</p>
            </div>
          </div>
        )}
      </div>

      {/* Chart and Additional Cards */}
      <div className="row mt-5 g-4">
        {/* Chart */}
        <div className="col-md-8 col-sm-12">
          <div
            style={{
              background: '#fff',
              borderRadius: '15px',
              boxShadow: '0 4px 20px rgba(0, 0, 0, 0.1)',
              padding: '20px',
              height: '100%',
            }}
          >
            <h4 className="mb-4">Dashboard Summary</h4>
            <ResponsiveContainer width="100%" height={320}>
              <BarChart
                data={data}
                margin={{ top: 20, right: 30, left: 10, bottom: 20 }}
              >
                <defs>
                  <linearGradient id="barColor" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor="orange" stopOpacity={0.9} />
                    <stop offset="100%" stopColor="orange" stopOpacity={0.7} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="4 4" stroke="#e0e0e0" />
                <XAxis dataKey="name" tick={{ fill: '#333', fontSize: 13 }} />
                <YAxis tick={{ fill: '#333', fontSize: 13 }} />
                <Tooltip
                  contentStyle={{
                    backgroundColor: '#f9f9f9',
                    border: 'none',
                    borderRadius: '10px',
                  }}
                  labelStyle={{ fontWeight: 'bold', color: 'orange' }}
                />
                <Legend iconType="circle" wrapperStyle={{ fontSize: '14px' }} />
                <Bar
                  dataKey="value"
                  fill="url(#barColor)"
                  barSize={45}
                  radius={[12, 12, 0, 0]}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Side Cards */}
        <div className="col-md-12 col-lg-4 col-sm-12">
          <div className="row g-3">
            <div className=" col-md-8 col-lg-12 col-sm-12">
              <div className="card-four text-dark p-4 rounded-4 shadow text-center">
              <div className='w-25 rounded-2 bg-warning mt-4 ms-4' style={{ height: '50px' }}>
                <FaUserPlus className="icon-style  fs-2 text-white mt-2" />
                </div>
                <h5 style={{ marginTop: '-50px' }} className='ms-5'>New Sign-ups</h5>
                <p className="fs-4 ms-5 fw-bold">120</p>
              </div>
            </div>
            <div className=" col-md-8 col-lg-12 col-sm-12">
              <div className="card-four text-dark p-4 rounded-4 shadow text-center">
               <div className='w-25 rounded-2 bg-warning mt-4 ms-4' style={{ height: '50px' }}>
                <FaVideo className="icon-style fs-2 text-white mt-2" />
                </div>
                <h5 style={{ marginTop: '-50px' }} className='ms-5'>Admin Videos</h5>
                <p className="fs-4 ms-5 fw-bold">{adminVideoCount}</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Home;
