import React, { useEffect, useState } from 'react';
import { FaTrash } from 'react-icons/fa';
import axios from "../Https/Axios";
import { VideoList } from "../Https/AdminSideAxiosUrls";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

const AllVideosList = () => {
  const [videos, setVideos] = useState([]);
  const [playingVideoId, setPlayingVideoId] = useState(null);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    fetchVideos();
  }, []);

  const fetchVideos = async () => {
    setLoading(true);
    try {
      const res = await axios.get(VideoList);
      setTimeout(() => {
        setVideos(res.data);
        setLoading(false);
      }, 2000);
    } catch (error) {
      console.error('Error fetching videos:', error);
      setLoading(false);
      toast.error("Failed to load videos");
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this video?')) return;
    try {
      await axios.delete(`${VideoList}/${id}`);
      setVideos(videos.filter((video) => video._id !== id));
      toast.success("Video deleted successfully");
    } catch (error) {
      console.error('Error deleting video:', error);
      toast.error("Failed to delete video");
    }
  };

  const handleSearch = (e) => {
    setSearchTerm(e.target.value);
  };

  const getVideoId = (url) => {
    const regExp = /^.*(?:youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
    const match = url.match(regExp);
    return match && match[1].length === 11 ? match[1] : null;
  };

  return (
    <div className="container">
      <ToastContainer />

      {/* Search Bar */}
      <div className='d-flex flex-wrap my-3'>
        <div className="col-md-6 col-sm-12 w-75">
          <input
            type="text"
            className="form-control rounded-5 p-2 w-100 bg-light ms-4"
            placeholder="Search..."
            value={searchTerm}
            onChange={handleSearch}
          />
        </div>
        <div className="col-md-3 col-sm-12">
          <button className="btn bg-warning w-50 rounded-5 p-2 ms-5 fw-bold text-white">Search</button>
        </div>
      </div>

      {loading ? (
        <div className="spinner-wrapper">
          <div className="spinner-square">
            <div className="square-1 square"></div>
            <div className="square-2 square"></div>
            <div className="square-3 square"></div>
          </div>
        </div>
      ) : (
        <div className="row">
          {videos
            .filter((video) =>
              video.title.toLowerCase().includes(searchTerm.toLowerCase())
            )
            .map((video) => {
              const videoId = getVideoId(video.url);
              const isPlaying = playingVideoId === video._id;

              return (
                <div key={video._id} className="col-md-8 col-sm-12 col-lg-4 mb-4">
                  <div className="card h-100 shadow">
                    <div
                      className="thumbnail"
                      onClick={() => setPlayingVideoId(isPlaying ? null : video._id)}
                    >
                      {isPlaying ? (
                        <iframe
                          src={`https://www.youtube.com/embed/${videoId}?autoplay=1`}
                          title={video.title}
                          allow="autoplay; encrypted-media"
                          allowFullScreen
                          width="100%"
                          height="200"
                        />
                      ) : (
                        <img
                          src={`https://img.youtube.com/vi/${videoId}/0.jpg`}
                          alt={video.title}
                          className="card-img-top"
                          style={{ height: "200px", objectFit: "cover" }}
                        />
                      )}
                    </div>
                    <div className="card-body">
                      <h5 className="card-title">{video.title}</h5>
                      <p className='text-start'><strong>Upload by:</strong> {video.uploadedBy?.name || 'N/A'}</p>
                      <p className='text-start'><strong>Email:</strong> {video.uploadedBy?.email || 'N/A'}</p>
                      <p className='text-start'><strong>Category:</strong> {video.category || 'N/A'}</p>
                      <p className='text-start'><strong>Comments:</strong> {video.comments?.length > 0 ? video.comments.join(', ') : 'N/A'}</p>
                      <p className='text-start'><strong>Tags:</strong> {video.tags?.length > 0 ? video.tags.join(', ') : 'N/A'}</p>
                    </div>
                    <div className="card-footer text-end bg-white">
                      <button onClick={() => handleDelete(video._id)} className="btn bg-warning">
                        <FaTrash /> Delete
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
        </div>
      )}
    </div>
  );
};

export default AllVideosList;
