import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import LoginForm from './components/LoginForm';
import Sidebar from './components/Sidebar';
import './App.css';
import Home from './components/Home';
import ParentList from './components/ParentList';
import AllVideoList from './components/AllVideosList';
import AdminVideoList from './components/AdminVideoList';
import { ToastContainer } from 'react-toastify'; // Import ToastContainer
import 'bootstrap/dist/css/bootstrap.min.css';
import 'react-toastify/dist/ReactToastify.css'; // Import the Toastify CSS

const DashboardLayout = ({ children }) => (
  <div style={{ display: 'flex' }}>
    <Sidebar />
    <div style={{ marginLeft: '250px', padding: '20px', flex: 1 }}>
      {children}
    </div>
  </div>
);

const ProtectedRoute = ({ children }) => {
  const isAuth = localStorage.getItem('auth');
  return isAuth ? children : <Navigate to="/" />;
};

const App = () => {
  return (
    <> 
      <ToastContainer /> 
      <Routes>
        <Route path="/" element={<LoginForm />} />
        <Route
          path="/dashboard/*"
          element={
            <ProtectedRoute>
              <DashboardLayout>
                <Routes>
                  <Route path="/Home" element={<Home />} />
                  <Route path="/ParentList" element={<ParentList />} />
                  <Route path="/AllVideoList" element={<AllVideoList />} />
                  <Route path="/AdminVideoList" element={<AdminVideoList />} />
                </Routes>
              </DashboardLayout>
            </ProtectedRoute>
          }
        />
      </Routes>
      </>
  );
};

export default App;
