import React, { useState, useEffect } from "react";
import { FaSearch, FaUser, FaEnvelope } from "react-icons/fa";
import axios from "../Https/Axios";
import { ParentsList, RegisterParent } from "../Https/AdminSideAxiosUrls";
import { ToastContainer, toast } from "react-toastify";
import 'react-toastify/dist/ReactToastify.css';
import { ClipLoader } from "react-spinners"; // Importing the spinner

export default function ParentList() {
  const [parents, setParents] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [selectedParent, setSelectedParent] = useState(null);
  const [editForm, setEditForm] = useState({ name: "", email: "" });
  const [loading, setLoading] = useState(false); // Loading state for fetch, add, and edit
  const [showAddModal, setShowAddModal] = useState(false);
  const [addForm, setAddForm] = useState({ name: "", email: "", password: "" });

  const fetchParents = async () => {
    setLoading(true);
    try {
      const res = await axios.get(ParentsList);
      setParents(res.data);
    } catch (err) {
      toast.error("Failed to load parents");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchParents();
  }, []);

  const handleSearch = (e) => setSearchTerm(e.target.value);

  const openModal = (parent) => {
    setSelectedParent(parent);
    setEditForm({ name: parent.name, email: parent.email });
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setSelectedParent(null);
    setEditForm({ name: "", email: "" });
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    if (showAddModal) {
      setAddForm({ ...addForm, [name]: value });
    } else {
      setEditForm({ ...editForm, [name]: value });
    }
  };

  const updateParent = async () => {
    if (!editForm.name || !editForm.email) {
      toast.warning("Please fill in both name and email");
      return;
    }
    setLoading(true);
    try {
      await axios.put(`${ParentsList}/${selectedParent._id}`, editForm);
      toast.success("Parent updated successfully");
      fetchParents();
      closeModal();
    } catch (err) {
      toast.error("Error updating parent");
    } finally {
      setLoading(false);
    }
  };

  const deleteParent = async (id) => {
    if (!window.confirm("Delete this parent?")) return;
    setLoading(true);
    try {
      await axios.delete(`${ParentsList}/${id}`);
      toast.success("Deleted successfully");
      fetchParents();
    } catch (err) {
      toast.error("Error deleting parent");
    } finally {
      setLoading(false);
    }
  };

  const openAddModal = () => {
    setShowAddModal(true);
    setAddForm({ name: "", email: "", password: "" });
  };

  const closeAddModal = () => {
    setShowAddModal(false);
    setAddForm({ name: "", email: "", password: "" });
  };

  const addParent = async () => {
    if (!addForm.name || !addForm.email || !addForm.password) {
      toast.warning("Please fill all fields");
      return;
    }
    setLoading(true);
    try {
      const res = await axios.post(RegisterParent, addForm);
      if (res.status === 200 || res.status === 201) {
        toast.success("Parent added successfully");
        fetchParents(); // Refresh list
        closeAddModal(); // Close modal
      } else {
        toast.error("Failed to add parent");
      }
    } catch (error) {
      console.error("Error:", error);
      toast.error("Parent already exists");
    } finally {
      setLoading(false);
    }
  };

  const filteredParents = parents.filter((p) =>
    p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      <ToastContainer />
      <div className="main">
        <div className="row mb-4">
          <div className="col-md-6 col-sm-12 w-75">
            <input
              type="text"
              className="form-control rounded-5 p-2 w-100 bg-light ms-4"
              placeholder="Search..."
              value={searchTerm}
              onChange={handleSearch}
            />
          </div>
          <div className="col-md-3 col-sm-12">
            <button
              className="btn bg-warning w-50 rounded-5 p-2 ms-2 fw-bold text-white"
              onClick={openAddModal}
              disabled={loading} // Disable the button while loading
            >
              {loading ? <ClipLoader size={20} color="orange" /> : "Add Parent"}
            </button>
          </div>
        </div>

        <div className="parent-list-container col-lg-12">
          {loading ? (
            <div className="spinner-container">
              <ClipLoader size={50} color="orange" />
            </div>
          ) : (
            filteredParents.map((parent) => (
              <div key={parent._id} className="parent-card">
                <div className="parent-email" style={{ display: 'flex', gap: '10px' }}>
                  <FaUser style={{ marginTop: '5px' }} />
                  <div>
                    <strong>Name:</strong> {parent.name}
                    <hr style={{ transform: 'translate(-22px, -7px)', width: '280px' }} />
                  </div>
                </div>
                <div className="parent-email" style={{ display: 'flex', gap: '10px' }}>
                  <FaEnvelope style={{ marginTop: '5px' }} />
                  <div>
                    <strong>Email:</strong> {parent.email}
                    <hr style={{ transform: 'translate(-22px, -7px)', width: '280px' }} />
                  </div>
                </div>
                <div className="parent-actions">
                  <button className="edit-button" onClick={() => openModal(parent)} disabled={loading}>
                    {loading ? <ClipLoader size={20} color="#fff" /> : "Edit"}
                  </button>
                  <button className="delete-button" onClick={() => deleteParent(parent._id)} disabled={loading}>
                    {loading ? <ClipLoader size={20} color="#fff" /> : "Delete"}
                  </button>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Edit Modal */}
        {showModal && (
          <div className="modal-overlay">
            <div className="modal-dialog">
              <div className="modal-content">
                <div className="modal-header">
                  <h5 className="modal-title">Edit Parent</h5>
                  <button type="button" className="close" onClick={closeModal}>
                    &times;
                  </button>
                </div>
                <div className="modal-body">
                  <form>
                    <label>Name:</label>
                    <input
                      name="name"
                      value={editForm.name}
                      onChange={handleChange}
                      className="modal-input"
                    />
                    <label>Email:</label>
                    <input
                      name="email"
                      value={editForm.email}
                      onChange={handleChange}
                      className="modal-input"
                    />
                  </form>
                </div>
                <div className="modal-footer ">
                  <button className="btn bg-warning" onClick={closeModal}>
                    Cancel
                  </button>
                  <button className="btn ms-2 bg-warning" onClick={updateParent}>
                    {loading ? <ClipLoader size={20} color="#fff" /> : "Save Changes"}
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Add Parent Modal */}
        {showAddModal && (
          <div className="modal-overlay">
            <div className="modal-dialog">
              <div className="modal-content">
                <div className="modal-header">
                  <h5 className="modal-title">Add Parent</h5>
                  <button type="button" className="close" onClick={closeAddModal}>
                    &times;
                  </button>
                </div>
                <div className="modal-body">
                  <form>
                    <label>Name:</label>
                    <input
                      name="name"
                      value={addForm.name}
                      onChange={handleChange}
                      className="modal-input"
                    />
                    <label>Email:</label>
                    <input
                      name="email"
                      value={addForm.email}
                      onChange={handleChange}
                      className="modal-input"
                    />
                    <label>Password:</label>
                    <input
                      name="password"
                      type="password"
                      value={addForm.password}
                      onChange={handleChange}
                      className="modal-input"
                    />
                  </form>
                </div>
                <div className="modal-footer">
                  <button className="btn bg-warning" onClick={closeAddModal}>
                    Cancel
                  </button>
                  <button className="btn ms-2  bg-warning" onClick={addParent}>
                    {loading ? <ClipLoader size={20} color="#fff" /> : "Add Parent"}
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </>
  );
}
